// AUTO-GENERATED CONTENT NOTE:
// The CHARACTERS / MARKS / QUALITIES / UNLOCKS data below was transcribed from the reference
// chart (image.png) — every cell's item name was read from the chart and every cell's quality
// colour was sampled from the chart's own pixels and matched against its KEY palette.
// Wiki filenames were verified against https://bindingofisaacrebirth.wiki.gg (build time only).
// This module is the single source of truth for both the app and scripts/scrape-assets.ts.

export type QualityKey =
  | "q4" | "q3" | "q2" | "q1" | "q0"
  | "trinket" | "coop" | "character" | "feature" | "consumable";

export interface Character {
  id: string;
  label: string;
  /** Wiki file name — used by scripts/scrape-assets.ts only, never at runtime. */
  wikiFile: string;
  tainted: boolean;
}

export interface Mark {
  id: string;
  label: string;
  /** Boss portrait shown in the row header. */
  bossFile: string;
  /** In-game completion-mark icon, shown in Completion Mark mode. */
  markFile: string;
}

export interface Unlock {
  item: string;
  wikiFile: string;
  quality: QualityKey;
}

export type CharId = (typeof CHARACTERS)[number]["id"];
export type MarkId = (typeof MARKS)[number]["id"];

/** Sparse: UNLOCKS[charId]?.[markId] — a missing entry is a NO UNLOCK cell. */
export type UnlockMatrix = Partial<Record<string, Partial<Record<string, Unlock>>>>;

/** User completion state per cell. */
export type CellState = 0 | 1 | 2; // 0 none · 1 normal · 2 hard

