/** Local sprite slug for an unlock's wiki file — mirrors scripts/scrape-assets.ts. */
export function itemSlug(wikiFile: string): string {
  return wikiFile.replace(/\.png$/i, "").replace(/[^a-z0-9]+/gi, "_").toLowerCase();
}
